  OPTIONAL { ?director dbo:birthDate ?director_bdate }
  OPTIONAL { ?film rdfs:label ?film_label FILTER(lang(?film_label) = "en") }
  OPTIONAL { ?director rdfs:label ?director_label FILTER(lang(?director_label) = "en") }
} ORDER BY ?film_label

